insert into sentences (id, chapter_id, position, text_en, paragraph) values
(1, 'oz-01', 1, 'Dorothy is a little girl.', true),
(2, 'oz-01', 2, 'She lives in Kansas, in the middle of a big, grey land.', false),
(3, 'oz-01', 3, 'She lives with Uncle Henry and Aunt Em.', false),
(4, 'oz-01', 4, 'Uncle Henry has a small farm.', false),
(5, 'oz-01', 5, 'Their house is very small.', true),
(6, 'oz-01', 6, 'It has only one room.', false),
(7, 'oz-01', 7, 'There is a dark hole in the floor.', false),
(8, 'oz-01', 8, 'In a big storm, the family can go into the hole.', false),
(9, 'oz-01', 9, 'Everything around the house is grey.', true),
(10, 'oz-01', 10, 'The grass is grey, and the house is grey.', false),
(11, 'oz-01', 11, 'Aunt Em is thin and grey too.', false),
(12, 'oz-01', 12, 'She never smiles.', false),
(13, 'oz-01', 13, 'Uncle Henry never laughs.', false),
(14, 'oz-01', 14, 'He works from morning to night.', false),
(15, 'oz-01', 15, 'But Dorothy is not grey and sad.', true),
(16, 'oz-01', 16, 'She has a little black dog.', false),
(17, 'oz-01', 17, 'His name is Toto.', false),
(18, 'oz-01', 18, 'Toto has long hair and small black eyes.', false),
(19, 'oz-01', 19, 'He plays all day, and Dorothy laughs with him.', false),
(20, 'oz-01', 20, 'She loves Toto very much.', false),
(21, 'oz-01', 21, 'Today Toto and Dorothy do not play.', true),
(22, 'oz-01', 22, 'Uncle Henry looks at the sky.', false),
(23, 'oz-01', 23, 'The sky is very grey today.', false),
(24, 'oz-01', 24, 'Then they hear a strong wind.', false),
(25, 'oz-01', 25, '“A storm is coming, Em!” says Uncle Henry.', false),
(26, 'oz-01', 26, 'He runs to the animals.', false),
(27, 'oz-01', 27, '“Quick, Dorothy! Go into the hole!” says Aunt Em.', true),
(28, 'oz-01', 28, 'Toto runs under the bed.', false),
(29, 'oz-01', 29, 'Dorothy runs after him.', false),
(30, 'oz-01', 30, 'Aunt Em goes down into the hole.', false),
(31, 'oz-01', 31, 'Dorothy finds Toto under the bed.', false),
(32, 'oz-01', 32, 'Then the house shakes.', false),
(33, 'oz-01', 33, 'Dorothy sits down on the floor.', false),
(34, 'oz-01', 34, 'The wind turns it around and around.', false),
(35, 'oz-01', 35, 'Then the house goes up into the sky!', false),
(36, 'oz-01', 36, 'The house flies in the wind for many hours.', true),
(37, 'oz-01', 37, 'Dorothy and Toto are alone in the house.', false),
(38, 'oz-01', 38, 'Toto falls into the hole in the floor.', false),
(39, 'oz-01', 39, 'Dorothy pulls him out by his ear.', false),
(40, 'oz-01', 40, 'Dorothy is very tired.', false),
(41, 'oz-01', 41, 'Then she goes to her bed with Toto.', false),
(42, 'oz-01', 42, 'The house flies and shakes, but Dorothy sleeps.', false),
(43, 'oz-02', 1, 'Dorothy wakes up.', true),
(44, 'oz-02', 2, 'The house is on the ground now.', false),
(45, 'oz-02', 3, 'She opens the door with Toto in her arms.', false),
(46, 'oz-02', 4, 'She sees a beautiful country.', false),
(47, 'oz-02', 5, 'There is green grass, and there are tall trees.', false),
(48, 'oz-02', 6, 'There are birds and flowers everywhere.', false),
(49, 'oz-02', 7, 'Some little people come to the house.', true),
(50, 'oz-02', 8, 'They are the Munchkins.', false),
(51, 'oz-02', 9, 'They wear blue clothes and round hats.', false),
(52, 'oz-02', 10, 'An old woman in white comes with them.', false),
(53, 'oz-02', 11, '“Welcome to the land of the Munchkins!” says the old woman.', true),
(54, 'oz-02', 12, '“Look! Your house is on the Wicked Witch of the East.”', false),
(55, 'oz-02', 13, '“She is dead now. Thank you!”', false),
(56, 'oz-02', 14, 'Dorothy looks under the house.', false),
(57, 'oz-02', 15, 'She sees two feet in silver shoes.', false),
(58, 'oz-02', 16, '“Oh, no!” says Dorothy.', false),
(59, 'oz-02', 17, '“Don''t be sad,” says the old woman.', false),
(60, 'oz-02', 18, '“She is a very bad witch. The Munchkins are free now.”', false),
(61, 'oz-02', 19, '“Who are you?” asks Dorothy.', true),
(62, 'oz-02', 20, '“I am the Witch of the North,” she says.', false),
(63, 'oz-02', 21, '“I am a good witch.”', false),
(64, 'oz-02', 22, '“There are four witches in the Land of Oz.”', false),
(65, 'oz-02', 23, '“The witches of the North and the South are good.”', false),
(66, 'oz-02', 24, '“The witches of the East and the West are wicked.”', false),
(67, 'oz-02', 25, 'Then the dead witch''s feet go away in the hot sun.', false),
(68, 'oz-02', 26, 'Only the silver shoes are there.', false),
(69, 'oz-02', 27, '“The shoes are for you,” says the Witch of the North.', false),
(70, 'oz-02', 28, '“I want to go home to Kansas,” says Dorothy.', true),
(71, 'oz-02', 29, '“Aunt Em and Uncle Henry are sad without me.”', false),
(72, 'oz-02', 30, 'The good witch thinks.', false),
(73, 'oz-02', 31, 'Then she says, “Go to the Emerald City.”', false),
(74, 'oz-02', 32, '“The great Wizard Oz lives there. He can help you.”', false),
(75, 'oz-02', 33, '“Walk on the yellow brick road.”', false),
(76, 'oz-02', 34, '“Can you come with me?” asks Dorothy.', false),
(77, 'oz-02', 35, '“No, I can''t. But I can give you my kiss.”', false),
(78, 'oz-02', 36, 'The good witch kisses Dorothy on the forehead.', true),
