(82, 'oz-03', 1, 'Dorothy puts on the silver shoes.', true),
(83, 'oz-03', 2, 'They are just right for her feet.', false),
(84, 'oz-03', 3, 'Then she walks on the yellow brick road with Toto.', false),
(85, 'oz-03', 4, 'The sun is bright, and the birds sing.', false),
(86, 'oz-03', 5, 'After some hours, Dorothy is tired.', true),
(87, 'oz-03', 6, 'She sits down near a big field of corn.', false),
(88, 'oz-03', 7, 'In the field, there is a scarecrow on a pole.', false),
(89, 'oz-03', 8, 'His head is a small bag of straw.', false),
(90, 'oz-03', 9, 'He has a painted face and an old blue hat.', false),
