(92, 'oz-03', 11, '“Good day,” says the Scarecrow.', false),
(93, 'oz-03', 12, '“Can you talk?” asks Dorothy.', false),
(94, 'oz-03', 13, '“Yes, I can,” he says. “How are you?”', false),
(95, 'oz-03', 14, '“I am well, thank you,” says Dorothy. “And how are you?”', false),
(96, 'oz-03', 15, '“I am not very well,” says the Scarecrow.', false),
(97, 'oz-03', 16, '“I am on this pole day and night.”', false),
(98, 'oz-03', 17, '“Please take me down.”', false),
(99, 'oz-03', 18, 'Dorothy takes him down from the pole.', true),
(100, 'oz-03', 19, 'He is very light, because he is only straw.', false),
(101, 'oz-03', 20, '“Thank you!” he says. “Now I feel like a new man.”', false),
(102, 'oz-03', 21, '“Who are you, and where are you going?”', false),
(103, 'oz-03', 22, '“My name is Dorothy,” she says.', false),
(104, 'oz-03', 23, '“I am going to the Emerald City.”', false),
(105, 'oz-03', 24, '“I want to ask Oz to send me home to Kansas.”', false),
(106, 'oz-03', 25, '“Who is Oz?” asks the Scarecrow.', true),
(107, 'oz-03', 26, '“Don''t you know?” asks Dorothy.', false),
(108, 'oz-03', 27, '“No, I don''t know anything,” he says sadly.', false),
(109, 'oz-03', 28, '“My head is full of straw. I have no brains.”', false),
(110, 'oz-03', 29, '“The crows know this, and they are not afraid of me.”', false),
(111, 'oz-03', 30, '“Can Oz give me some brains?”', false),
(112, 'oz-03', 31, '“I don''t know,” says Dorothy. “But you can come with me.”', false),
(113, 'oz-03', 32, '“Maybe Oz can help you too.”', false),
(114, 'oz-03', 33, 'The Scarecrow is very happy.', true),
(115, 'oz-03', 34, '“I am afraid of only one thing,” he says.', false),
(116, 'oz-03', 35, '“What is it?” asks Dorothy.', false),
(117, 'oz-03', 36, '“Fire,” says the Scarecrow.', false),
(118, 'oz-03', 37, 'So the new friends walk on the yellow brick road together.', false),
(119, 'oz-04', 1, 'The next day, Dorothy and the Scarecrow walk into a forest.', true),
(120, 'oz-04', 2, 'There are many tall trees, and it is dark.', false),
(121, 'oz-04', 3, 'Suddenly they hear a sad sound.', false),
(122, 'oz-04', 4, 'They look and see a strange man between the trees.', false),
(123, 'oz-04', 5, 'He is a man of tin.', false),
(124, 'oz-04', 6, 'He has an axe in his hands, but he does not move.', false),
(125, 'oz-04', 7, 'Dorothy goes to him. “Can we help you?” she asks.', true),
(126, 'oz-04', 8, '“Yes, please,” says the Tin Woodman.', false),
(127, 'oz-04', 9, '“My arms and legs rust in the rain. Now I cannot move.”', false),
(128, 'oz-04', 10, '“There is an oil can in my little house.”', false),
