(135, 'oz-04', 17, '“Why are you in this forest?”', false),
(136, 'oz-04', 18, '“We are going to the Emerald City,” says Dorothy.', false),
(137, 'oz-04', 19, '“I want to go home, and the Scarecrow wants some brains.”', false),
(138, 'oz-04', 20, 'The Tin Woodman thinks.', true),
(139, 'oz-04', 21, 'Then he says, “Can Oz give me a heart?”', false),
(140, 'oz-04', 22, '“I am all tin, and there is no heart in me.”', false),
(141, 'oz-04', 23, '“Without a heart, I cannot love.”', false),
(142, 'oz-04', 24, '“Then come with us,” says Dorothy.', false),
(143, 'oz-04', 25, '“Maybe Oz can help all of us.”', false),
(144, 'oz-04', 26, '“I want brains, not a heart,” says the Scarecrow.', true),
(145, 'oz-04', 27, '“Without brains, I cannot use a heart.”', false),
(146, 'oz-04', 28, '“I want a heart,” says the Tin Woodman.', false),
(147, 'oz-04', 29, '“Brains do not make you happy. A heart does.”', false),
(148, 'oz-04', 30, 'Dorothy says nothing. Who is right? She does not know.', false),
(149, 'oz-04', 31, 'The Tin Woodman takes his axe and the oil can.', true),
(150, 'oz-04', 32, '“Rain is very bad for me,” he says.', false),
(151, 'oz-04', 33, 'Now three friends walk on the yellow brick road.', false),
(152, 'oz-04', 34, 'In the dark forest, the Tin Woodman cuts a way with his axe.', false),
(153, 'oz-05', 1, 'The friends walk on through the dark forest.', true),
(154, 'oz-05', 2, 'Suddenly they hear a loud roar.', false),
(155, 'oz-05', 3, 'A big lion jumps onto the road!', false),
(156, 'oz-05', 4, 'He hits the Scarecrow with his big paw.', false),
(157, 'oz-05', 5, 'The Scarecrow falls on the road.', false),
(158, 'oz-05', 6, 'Then the Lion hits the Tin Woodman.', false),
(159, 'oz-05', 7, 'The Tin Woodman falls too, but the tin is strong.', false),
(160, 'oz-05', 8, 'Little Toto runs at the Lion and barks.', true),
(161, 'oz-05', 9, 'The Lion opens his big mouth. He wants to bite Toto.', false),
(162, 'oz-05', 10, 'Dorothy is afraid for Toto, but she runs to the Lion.', false),
(163, 'oz-05', 11, 'She hits him on the nose with her hand.', false),
(164, 'oz-05', 12, '“Don''t bite Toto!” she says.', false),
(165, 'oz-05', 13, '“You are a big animal, and he is a little dog!”', false),
(166, 'oz-05', 14, '“You are a big coward!”', false),
(167, 'oz-05', 15, 'The Lion puts his paw on his nose.', true),
(168, 'oz-05', 16, '“Yes, I know,” he says sadly.', false),
(169, 'oz-05', 17, '“I am a coward. I am afraid of everything.”', false),
(170, 'oz-05', 18, '“But all the animals think a lion is brave.”', false),
