(174, 'oz-05', 22, 'The Lion looks at the Scarecrow.', true),
(175, 'oz-05', 23, '“Is he full of straw?” he asks.', false),
(176, 'oz-05', 24, '“Yes,” says Dorothy. “And the other man is tin.”', false),
(177, 'oz-05', 25, '“And what is this little animal?”', false),
(178, 'oz-05', 26, '“He is my dog, Toto,” says Dorothy.', false),
(179, 'oz-05', 27, '“Where are you all going?” asks the Lion.', true),
(180, 'oz-05', 28, '“We are going to the great Oz,” says the Tin Woodman.', false),
(181, 'oz-05', 29, '“He can give the Scarecrow brains and give me a heart.”', false),
