(185, 'oz-05', 33, '“Come with us,” says Dorothy.', true),
(186, 'oz-05', 34, '“You can keep the other animals away from us.”', false),
(187, 'oz-05', 35, 'So the Cowardly Lion walks with them on the yellow brick road.', false),
