(191, 'oz-06', 3, '“I can jump over it,” says the Lion.', false),
(192, 'oz-06', 4, 'He carries his friends on his back, one by one.', false),
(193, 'oz-06', 5, 'Strange beasts live in this forest. They are the Kalidahs.', true),
(194, 'oz-06', 6, 'They have bodies like bears and heads like tigers.', false),
(195, 'oz-06', 7, 'Soon the friends hear the Kalidahs behind them!', false),
(196, 'oz-06', 8, 'There is another ditch in the road.', false),
(197, 'oz-06', 9, 'The Tin Woodman cuts a big tree with his axe.', false),
