(201, 'oz-06', 13, 'Then the friends come to a big river.', true),
(202, 'oz-06', 14, '“How can we go over the water?” asks Dorothy.', false),
(203, 'oz-06', 15, 'The Tin Woodman makes a raft from trees.', false),
(204, 'oz-06', 16, 'They go over the river on the raft.', false),
(205, 'oz-06', 17, 'On the other side, there is a big field of red flowers.', true),
(206, 'oz-06', 18, 'They are poppies.', false),
(207, 'oz-06', 19, 'The poppies smell very strong.', false),
