(219, 'oz-06', 31, '“Please help our friend, the Lion,” says the Scarecrow.', false),
(220, 'oz-06', 32, 'The Tin Woodman makes a little cart.', false),
(221, 'oz-06', 33, 'Then many, many mice come.', false),
(222, 'oz-06', 34, 'Together they pull the Lion out of the field on the cart.', false),
