(224, 'oz-06', 36, 'She sees her friends and many little mice.', false),
(225, 'oz-06', 37, 'Then the Lion wakes up too.', false),
(226, 'oz-06', 38, '“Thank you, little mice!” he says.', false),
(227, 'oz-07', 1, 'The friends walk on the yellow brick road again.', true),
(228, 'oz-07', 2, 'After many days, they see a green light in the sky.', false),
(229, 'oz-07', 3, '“That is the Emerald City!” says Dorothy.', false),
(230, 'oz-07', 4, 'Soon they come to a big green wall.', false),
(231, 'oz-07', 5, 'In the wall, there is a big gate with emeralds on it.', false),
(232, 'oz-07', 6, 'Emeralds are beautiful green stones.', false),
(233, 'oz-07', 7, 'Dorothy rings a bell, and the gate opens.', true),
(234, 'oz-07', 8, 'A little man in green clothes is there.', false),
(235, 'oz-07', 9, 'He has a big green box.', false),
(236, 'oz-07', 10, '“I am the Guardian of the Gates,” he says. “Why are you here?”', false),
(237, 'oz-07', 11, '“We want to see the great Oz,” says Dorothy.', false),
(238, 'oz-07', 12, 'The little man is very surprised.', false),
(239, 'oz-07', 13, '“People do not often ask to see Oz,” he says.', false),
(240, 'oz-07', 14, '“He is great and terrible. But he is a good Wizard.”', false),
(241, 'oz-07', 15, '“I can take you to his palace.”', false),
(242, 'oz-07', 16, '“But first, you must put on these glasses.”', false),
(243, 'oz-07', 17, '“Why?” asks the Scarecrow.', false),
(244, 'oz-07', 18, '“The Emerald City is very bright,” says the Guardian.', false),
(245, 'oz-07', 19, '“Without glasses, the light can hurt your eyes.”', false),
(246, 'oz-07', 20, '“Everybody in the city wears green glasses, day and night.”', false),
(247, 'oz-07', 21, 'The Guardian opens his box. It is full of green glasses.', true),
(248, 'oz-07', 22, 'He puts glasses on Dorothy and all her friends.', false),
(249, 'oz-07', 23, 'Even little Toto has glasses!', false),
(250, 'oz-07', 24, 'Then the Guardian locks the glasses with a little key.', false),
(251, 'oz-07', 25, 'Now they walk into the Emerald City. Everything is green!', true),
(252, 'oz-07', 26, 'The houses are green, and the streets are green.', false),
(253, 'oz-07', 27, 'The windows are green, and even the sky is green.', false),
(254, 'oz-07', 28, 'The people wear green clothes, and their skin is a little green.', false),
(255, 'oz-07', 29, 'They look at the four strange friends.', false),
(256, 'oz-07', 30, 'There are many shops in the streets.', false),
(257, 'oz-07', 31, 'The shops sell green shoes, green hats and green sweets.', false),
