(294, 'oz-08', 33, '“Then I can give you courage.”', false),
(295, 'oz-08', 34, 'The friends are very sad.', true),
(296, 'oz-08', 35, '“What can we do?” asks the Tin Woodman.', false),
(297, 'oz-08', 36, '“We must go to the West,” says the Lion.', false),
(298, 'oz-08', 37, '“The Wicked Witch lives there, in the land of the Winkies.”', false),
(299, 'oz-08', 38, '“I am afraid of the Witch, but I can go with you.”', false),
(300, 'oz-08', 39, 'There is no road to the West.', false),
(301, 'oz-08', 40, 'But the next morning, the friends walk into the West.', false),
(302, 'oz-09', 1, 'The Wicked Witch of the West has only one eye.', true),
(303, 'oz-09', 2, 'But her eye is very strong, and it can see very far.', false),
(304, 'oz-09', 3, 'She sees Dorothy and her friends in her land.', false),
(305, 'oz-09', 4, 'The Witch is angry.', false),
(306, 'oz-09', 5, 'She blows her silver whistle, and forty wolves come.', false),
(307, 'oz-09', 6, '“Go and kill them!” she says.', false),
(308, 'oz-09', 7, 'But the Tin Woodman kills all the wolves with his axe.', false),
(309, 'oz-09', 8, 'Then the Witch sends forty black crows.', true),
(310, 'oz-09', 9, 'The Scarecrow is not afraid of crows. He kills them all.', false),
(311, 'oz-09', 10, 'Then she sends a lot of black bees.', false),
(312, 'oz-09', 11, 'The Scarecrow puts his straw on Dorothy, Toto and the Lion.', false),
(313, 'oz-09', 12, 'The bees cannot hurt the Tin Woodman, because he is tin.', false),
(314, 'oz-09', 13, 'Soon all the bees are dead.', false),
(315, 'oz-09', 14, 'Now the Witch is very angry.', true),
(316, 'oz-09', 15, 'She has a Golden Cap.', false),
(317, 'oz-09', 16, 'With this cap, she can call the Winged Monkeys.', false),
(318, 'oz-09', 17, 'The monkeys come and fly at the friends.', false),
(319, 'oz-09', 18, 'They throw the Tin Woodman onto some rocks.', false),
(320, 'oz-09', 19, 'They take the straw out of the Scarecrow.', false),
(321, 'oz-09', 20, 'They take the Lion to the Witch''s castle.', false),
(322, 'oz-09', 21, 'But they do not hurt Dorothy, because of the good witch''s kiss.', false),
(323, 'oz-09', 22, 'They carry her and Toto to the castle too.', false),
(324, 'oz-09', 23, 'The Witch sees the kiss and the silver shoes.', true),
(325, 'oz-09', 24, 'She is afraid, but Dorothy does not know this.', false),
(326, 'oz-09', 25, '“You are my servant now,” says the Witch.', false),
(327, 'oz-09', 26, '“Work in my kitchen every day!”', false),
(328, 'oz-09', 27, 'Dorothy works very hard, and she is very sad.', false),
(329, 'oz-09', 28, 'Every night, she takes food to the Lion.', false),
(330, 'oz-09', 29, 'The Witch wants the silver shoes, because they are magic.', true),
(331, 'oz-09', 30, 'One day, Dorothy falls, and one shoe comes off.', false),
(332, 'oz-09', 31, 'The Witch steals it quickly.', false),
(333, 'oz-09', 32, '“Give me my shoe!” says Dorothy angrily.', false),
(334, 'oz-09', 33, '“No! It is my shoe now,” says the Witch, and she laughs.', false),
(335, 'oz-09', 34, 'Dorothy is very angry.', true),
(336, 'oz-09', 35, 'She takes a bucket of water and throws it on the Witch.', false),
(337, 'oz-09', 36, '“Oh, no! I am melting!” cries the Witch.', false),
(338, 'oz-09', 37, 'She gets smaller and smaller.', false),
(339, 'oz-09', 38, 'Soon she is only brown water on the floor.', false),
(340, 'oz-09', 39, 'Dorothy takes the silver shoe and puts it on again.', true),
(341, 'oz-09', 40, 'Then she runs to the Lion.', false),
(342, 'oz-09', 41, '“The Wicked Witch is dead!” she says. “We are free!”', false),
(343, 'oz-09', 42, 'The Winkies are free too, and they are very happy.', false),
(344, 'oz-10', 1, 'The Winkies help Dorothy and the Lion.', true),
(345, 'oz-10', 2, 'They find the Tin Woodman and make him new again.', false),
(346, 'oz-10', 3, 'They find the Scarecrow''s clothes and put new straw in them.', false),
(347, 'oz-10', 4, 'Then Dorothy takes the Golden Cap.', false),
(348, 'oz-10', 5, 'The Winged Monkeys carry the friends back to the Emerald City.', false),
(349, 'oz-10', 6, 'This time, they all go to the throne room together.', true),
(350, 'oz-10', 7, 'But there is nobody on the throne.', false),
(351, 'oz-10', 8, 'They only hear a voice.', false),
(352, 'oz-10', 9, '“I am Oz, the Great and Terrible. What do you want?”', false),
(353, 'oz-10', 10, '“The Wicked Witch of the West is dead,” says Dorothy.', false),
(354, 'oz-10', 11, '“Now please keep your promise.”', false),
(355, 'oz-10', 12, '“Come back tomorrow,” says the voice.', false),
(356, 'oz-10', 13, 'The Lion is angry, and he roars very loudly.', false),
(357, 'oz-10', 14, 'Toto is afraid. He jumps and hits a screen in the corner.', false),
(358, 'oz-10', 15, 'The screen falls down.', false),
(359, 'oz-10', 16, 'Behind the screen, there is a little old man.', true),
(360, 'oz-10', 17, 'He has no hair on his head.', false),
(361, 'oz-10', 18, '“Who are you?” asks the Tin Woodman.', false),
(362, 'oz-10', 19, '“I am Oz, the Great and Terrible,” says the little man.', false),
(363, 'oz-10', 20, '“But please don''t hurt me!”', false),
(364, 'oz-10', 21, '“You are not a great wizard?” asks Dorothy.', false),
(365, 'oz-10', 22, '“No, my dear. I am only a common man.”', false),
(366, 'oz-10', 23, '“You are a humbug!” says the Scarecrow.', false),
(367, 'oz-10', 24, '“Yes, I am a humbug,” says Oz sadly.', false),
(368, 'oz-10', 25, 'Then Oz tells them his story.', true),
(369, 'oz-10', 26, '“I am from Omaha. It is not far from Kansas.”', false),
(370, 'oz-10', 27, '“One day, my balloon flies up into the sky.”', false),
(371, 'oz-10', 28, '“The wind takes it to this land.”', false),
(372, 'oz-10', 29, '“The people see me come from the sky.”', false),
(373, 'oz-10', 30, '“So they think I am a great wizard.”', false),
(374, 'oz-10', 31, 'Now the friends know the truth.', true),
(375, 'oz-10', 32, 'But Oz wants to help them.', false),
(376, 'oz-10', 33, 'He puts bran and pins in the Scarecrow''s head.', false),
(377, 'oz-10', 34, '“Now you have new brains!” he says.', false),
(378, 'oz-10', 35, '“I feel very clever!” says the Scarecrow.', false),
(379, 'oz-10', 36, 'Then Oz gives the Tin Woodman a beautiful silk heart.', false),
(380, 'oz-10', 37, '“It is a good heart,” says the Tin Woodman happily.', false),
(381, 'oz-10', 38, 'Then Oz gives the Lion a green drink.', false),
(382, 'oz-10', 39, '“Drink this, and you can be brave,” says Oz.', false),
(383, 'oz-10', 40, 'The Lion drinks it. “Now I am full of courage!” he says.', false),
(384, 'oz-10', 41, 'The three friends are very happy.', false),
(385, 'oz-10', 42, '“But how can I go home?” asks Dorothy.', false),
(386, 'oz-11', 1, 'The next day, Oz makes a big balloon of green silk.', true),
(387, 'oz-11', 2, 'He fills it with hot air.', false),
(388, 'oz-11', 3, '“I can take you home in my balloon,” he says to Dorothy.', false),
(389, 'oz-11', 4, 'Dorothy is very happy.', false),
(390, 'oz-11', 5, '“The Scarecrow can be the new king of the city,” says Oz.', false),
(391, 'oz-11', 6, 'All the people of the city come to see the balloon.', true),
(392, 'oz-11', 7, 'Oz goes into the balloon. “Come, Dorothy! Quick!” he says.', false),
(393, 'oz-11', 8, 'But Toto runs after a little cat, and Dorothy runs after Toto.', false),
(394, 'oz-11', 9, 'She finds him and runs back to the balloon.', false),
(395, 'oz-11', 10, 'But the ropes break, and the balloon goes up into the sky!', false),
(396, 'oz-11', 11, '“Come back!” cries Dorothy. “I want to go too!”', false),
(397, 'oz-11', 12, '“I can''t come back, my dear,” says Oz. “Goodbye!”', false),
(398, 'oz-11', 13, 'Dorothy cries, and her friends are sad too.', false),
(399, 'oz-11', 14, 'Then the soldier with the green beard comes to them.', true),
(400, 'oz-11', 15, '“Go to Glinda, the Good Witch of the South,” he says.', false),
(401, 'oz-11', 16, '“She can help you.”', false),
(402, 'oz-11', 17, 'So Dorothy and her three friends walk to the South.', false),
(403, 'oz-11', 18, 'On the way, they come to some strange trees.', true),
(404, 'oz-11', 19, 'The trees fight! Their branches take the Scarecrow and throw him.', false),
(405, 'oz-11', 20, 'The Tin Woodman cuts a branch with his axe.', false),
(406, 'oz-11', 21, 'Then the trees let the friends go.', false),
(407, 'oz-11', 22, 'Next, they come to a land of china.', true),
(408, 'oz-11', 23, 'Everything here is china: the houses, the animals and the people.', false),
(409, 'oz-11', 24, 'The china people are very small, and they break easily.', false),
(410, 'oz-11', 25, '“Please be careful!” says a little china lady.', false),
(411, 'oz-11', 26, 'But the Lion''s tail hits a little china house, and it breaks.', false),
(412, 'oz-11', 27, 'The Lion is very sorry.', false),
(413, 'oz-11', 28, 'Next, they come to a big forest.', true),
(414, 'oz-11', 29, 'Many animals live there, and they are very afraid.', false),
(415, 'oz-11', 30, '“A terrible monster lives in this forest,” says a tiger.', false),
(416, 'oz-11', 31, '“It is like a big spider, and it eats animals.”', false),
(417, 'oz-11', 32, '“Please kill it, and you can be our king.”', false),
(418, 'oz-11', 33, 'The Lion is brave now. He finds the monster asleep.', false),
(419, 'oz-11', 34, 'With one hit of his big paw, he kills it.', false),
(420, 'oz-11', 35, 'Now the Lion is the King of the forest animals!', false),
(421, 'oz-11', 36, '“I can come back to you,” he says. “But first I must help Dorothy.”', false),
(422, 'oz-12', 1, 'Dorothy puts on the Golden Cap again.', true),
(423, 'oz-12', 2, 'The Winged Monkeys carry the friends to the land of Glinda.', false),
(424, 'oz-12', 3, 'Glinda lives in a red castle in the South.', false),
(425, 'oz-12', 4, 'Glinda is young and very beautiful.', true),
(426, 'oz-12', 5, 'She has red hair and blue eyes.', false),
(427, 'oz-12', 6, '“What can I do for you, my child?” she asks.', false),
(428, 'oz-12', 7, 'Dorothy tells her story.', false),
(429, 'oz-12', 8, '“I want to go home to Kansas,” she says.', false),
(430, 'oz-12', 9, '“That is my only wish.”', false),
(431, 'oz-12', 10, 'Glinda kisses her. “I can help you,” she says.', true),
(432, 'oz-12', 11, '“But first, please give me the Golden Cap.”', false),
(433, 'oz-12', 12, 'Dorothy gives her the cap.', false),
(434, 'oz-12', 13, 'Then Glinda asks the friends, “What do you want to do now?”', false),
(435, 'oz-12', 14, '“I want to go back to the Emerald City and rule it,” says the Scarecrow.', false),
(436, 'oz-12', 15, '“I want to rule the Winkies,” says the Tin Woodman.', false),
(437, 'oz-12', 16, '“And I want to be King of the forest,” says the Lion.', false),
(438, 'oz-12', 17, '“The Winged Monkeys can take you there,” says Glinda.', false),
(439, 'oz-12', 18, 'Then she gives the Golden Cap to the King of the Monkeys.', false),
(440, 'oz-12', 19, 'Now the monkeys are free.', false),
(441, 'oz-12', 20, '“But how can I go home?” asks Dorothy.', true),
(442, 'oz-12', 21, '“Your silver shoes can take you home,” says Glinda.', false),
(443, 'oz-12', 22, '“They have great power.”', false),
(444, 'oz-12', 23, '“They can carry you over the desert to any place in the world.”', false),
(445, 'oz-12', 24, '“Knock your heels together three times.”', false),
(446, 'oz-12', 25, '“Then say where you want to go.”', false),
(447, 'oz-12', 26, 'Now Dorothy must say goodbye.', true),
(448, 'oz-12', 27, 'She kisses the Lion and the Tin Woodman.', false),
(449, 'oz-12', 28, 'The Tin Woodman cries.', false),
(450, 'oz-12', 29, 'She hugs the Scarecrow.', false),
(451, 'oz-12', 30, 'Then she takes Toto in her arms.', false),
(452, 'oz-12', 31, 'She knocks her heels together three times.', false),
(453, 'oz-12', 32, '“Take me home to Aunt Em!” she says.', false),
(454, 'oz-12', 33, 'The wind takes her up into the sky.', true),
(455, 'oz-12', 34, 'Then she falls onto soft green grass.', false),
(456, 'oz-12', 35, 'She looks around. She is in Kansas!', false),
(457, 'oz-12', 36, 'There is a new house on the farm, and Uncle Henry is near it.', false),
(458, 'oz-12', 37, 'The silver shoes are not on her feet now.', false),
(459, 'oz-12', 38, 'Aunt Em comes out of the house.', true),
(460, 'oz-12', 39, 'She sees Dorothy and runs to her.', false),
(461, 'oz-12', 40, '“My dear child!” she cries, and she hugs Dorothy.', false),
(462, 'oz-12', 41, '“Where are you coming from?”', false),
(463, 'oz-12', 42, '“From the Land of Oz,” says Dorothy. “And here is Toto too.”', false),
(464, 'oz-12', 43, '“Oh, Aunt Em! I''m so glad to be at home again!”', false);

